def get_reachability(edges):
    N = 0
    if not edges: return set()
    for s, b in edges:
        N = max(N, s, b)
    adj = {i: [] for i in range(1, N + 1)}
    for s, b in edges:
        adj[s].append(b)
    reach = set()
    for start_node in range(1, N + 1):
        stack = [start_node]
        visited = {start_node}
        while stack:
            u = stack.pop()
            if u != start_node:
                reach.add((start_node, u))
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    stack.append(v)
    return reach

import itertools

def solve_small(N):
    for k in range(1, N):
        from itertools import combinations
        s_choices = list(combinations(range(1, N + 1), k))
        b_choices = list(combinations(range(1, N + 1), k))
        all_valid_edge_sets = []
        for s in s_choices:
            for b in b_choices:
                if all(s[i] < b[i] for i in range(k)):
                    all_valid_edge_sets.append(list(zip(s, b)))

        guaranteed = True
        for i in range(len(all_valid_edge_sets)):
            for j in range(i, len(all_valid_edge_sets)):
                reach_A = get_reachability(all_valid_edge_sets[i])
                reach_B = get_reachability(all_valid_edge_sets[j])
                if not reach_A.intersection(reach_B):
                    guaranteed = False
                    break
            if not guaranteed:
                break
        if guaranteed:
            return k
    return None

